  ('Q_20261115_08_34', 'PG', 'Prakarya 8', 'Setelah sisik ikan direndam dengan deterjen selama 5-10 menit, langkah selanjutnya adalah ....', 'none', '', '["dibilas dengan air bersih", "dijemur di bawah terik matahari", "langsung dirangkai", "dikeringkan dengan setrika"]'::jsonb, '[]'::jsonb, 'dibilas dengan air bersih', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_35', 'PG', 'Prakarya 8', 'Ukuran produk 10 cm x 5 cm akan dikemas dengan kertas duplek yang dilebihkan 3 cm di setiap sisinya. Ukuran kertas duplek yang dipotong adalah ....', 'none', '', '["10 cm x 5 cm", "12 cm x 7 cm", "13 cm x 8 cm", "16 cm x 11 cm"]'::jsonb, '[]'::jsonb, '16 cm x 11 cm', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_36', 'PG', 'Prakarya 8', 'Desain produk kerajinan pada kegiatan perencanaan dibuat dengan tampilan ....', 'none', '', '["depan saja", "atas dan bawah", "belakang dan samping", "depan, atas, dan samping"]'::jsonb, '[]'::jsonb, 'depan, atas, dan samping', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_37', 'PG', 'Prakarya 8', 'Jika tidak tersedia bahan finishing seperti varnish dan lem kayu, maka alternatif bahan finishsing yang dapat digunakan adalah....', 'none', '', '["lem kanji", "lem tembak", "lem lilin", "lem alteco"]'::jsonb, '[]'::jsonb, 'lem kanji', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_38', 'PG', 'Prakarya 8', 'Teknik yang dapat digunakan untuk menyatukan bahan dalam pembuatan kerajinan adalah ....', 'none', '', '["Menggunting bahan", "menempel dan mengikat", "merendam bahan", "menghancurkan bahan"]'::jsonb, '[]'::jsonb, 'menempel dan mengikat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_39', 'PG', 'Prakarya 8', 'Kartu kecil pada kemasan yang menjelaskan bahwa produk dibuat dari limbah sisa produksi merupakan contoh nilai tambah berupa ....', 'none', '', '["nilai historis", "merek produk", "nilai bahan", "nilai estetis"]'::jsonb, '[]'::jsonb, 'nilai bahan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_40', 'PG', 'Prakarya 8', 'Modal pembuatan sebuah kerajinan Rp50.000,00 dan pengrajin menginginkan laba 30%. Harga jual yang tepat adalah ....', 'none', '', '["Rp55.000,00", "Rp60.000,00", "Rp63.000,00", "Rp65.000,00"]'::jsonb, '[]'::jsonb, 'Rp65.000,00', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_41', 'PG', 'Prakarya 8', 'Seorang murid ingin membuat kerajinan dari biji-bijian. Agar produk memiliki nilai estetis tinggi, langkah yang paling tepat adalah ....', 'none', '', '["membuat desain terlebih dahulu dan memilih biji berdasarkan warna", "menggunakan biji secara acak tanpa rancangan", "menggunakan semua biji tanpa membersihkannya", "mencampurkan biji dengan sampah plastik"]'::jsonb, '[]'::jsonb, 'membuat desain terlebih dahulu dan memilih biji berdasarkan warna', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_42', 'PG', 'Prakarya 8', 'Singkatan ATM dalam mengembangkan promosi berarti ....', 'none', '', '["Atur, Tata, Mulai", "Amati, Tiru, Modifikasi", "Ambil, Tukar, Manfaatkan", "Analisis, Tulis, Mengulas"]'::jsonb, '[]'::jsonb, 'Amati, Tiru, Modifikasi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_43', 'PG', 'Prakarya 8', 'Pemasaran online (e-commerce) hanya dapat dilakukan apabila suatu daerah ....', 'none', '', '["memiliki pameran tahunan", "memiliki toko kerajinan", "terhubung dengan jaringan internet", "memiliki pabrik besar"]'::jsonb, '[]'::jsonb, 'terhubung dengan jaringan internet', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_44', 'PG', 'Prakarya 8', 'Dalam presentasi, guru dan peserta didik yang mendengarkan disebut ....', 'none', '', '["Presenter", "Media", "Moderator", "audiens"]'::jsonb, '[]'::jsonb, 'audiens', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_45', 'PG', 'Prakarya 8', 'Perhatikan kondisi berikut!<br><b>Sebuah</b><b> </b><b>daerah</b><b> </b><b>menghasilkan</b><b> </b><b>banyak</b><b> </b><b>tempurung</b><b> </b><b>kelapa</b><b> </b><b>dari</b><b> </b><b>usaha</b><b> </b><b>pengolahan</b><b> </b><b>kelapa</b><b>. Selama </b><b>ini</b><b> </b><b>tempurung</b><b> </b><b>tersebut</b><b> </b><b>hanya</b><b> </b><b>dibakar</b><b> </b><b>atau</b><b> </b><b>dibuang</b><b>.</b><br>Jika ingin meningkatkan nilai guna limbah tersebut, rancangan produk yang paling tepat adalah ....', 'none', '', '["membuat mangkuk, lampu hias, atau aksesori dari tempurung", "membakar seluruh tempurung hingga menjadi abu", "menjadikannya bahan bakar tanpa pengolahan", "mencampurkannya dengan sampah plastik"]'::jsonb, '[]'::jsonb, 'membuat mangkuk, lampu hias, atau aksesori dari tempurung', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_46', 'PG', 'Prakarya 8', 'Sekolah Bima berada di daerah pantai yang jauh dari kota sehingga clay sulit didapat, tetapi sisik ikan dan sisa tepung banyak tersedia. Bima ingin membuat aksesori bernilai jual dengan modal terjangkau. Keputusan yang paling tepat adalah ....', 'none', '', '["membeli clay dari kota agar hasil sama dengan contoh yang diinginkan", "membuat gantungan kunci dari sisa tepung dan bros dari sisik ikan yang sudah dibersihkan", "menggunakan plastik bekas karena lebih awet dan tahan air", "membatalkan proyek karena bahan tidak lengkap"]'::jsonb, '[]'::jsonb, 'membuat gantungan kunci dari sisa tepung dan bros dari sisik ikan yang sudah dibersihkan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_47', 'PG', 'Prakarya 8', 'Dua pengrajin membuat vas dari cangkang telur dengan kualitas sama. Pengrajin A menjual dengan kemasan biasa seharga Rp40.000,00. Pengrajin B menambahkan merek, kemasan kain tile, dan kartu cerita bahan limbah, lalu menjual seharga Rp55.000,00 dan tetap laku.<br>Pernyataan yang paling tepat menjelaskan hal tersebut adalah ....', 'none', '', '["Pengrajin B menggunakan bahan yang lebih mahal tetapi kualitasnya kerajinannya buruk", "Merek, kemasan, dan kartu cerita memberi nilai tambah sehingga harga jual dapat lebih tinggi", "Pembeli tidak memperhatikan harga walaupun mahal", "Pengrajin A menggunakan teknik yang salah"]'::jsonb, '[]'::jsonb, 'Merek, kemasan, dan kartu cerita memberi nilai tambah sehingga harga jual dapat lebih tinggi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_48', 'PG', 'Prakarya 8', 'Perhatikan langkah berikut!<br>1)	Menyiapkan alat dan bahan<br>2)	Membuat desain<br>3)	Finishing dan pengemasan<br>4)	Membuat produk<br>Urutan yang tepat dalam pembuatan kerajinan adalah ....', 'none', '', '["1-2-3-4", "2-4-1-3", "1-4-2-3", "2-1-4-3"]'::jsonb, '[]'::jsonb, '2-1-4-3', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_08_49', 'PG', 'Prakarya 8', 'Pada bazar kelas, produk tempat pensil dari serbuk kayu milik Sari kurang diminati. Hasil evaluasi menunjukkan bentuknya kurang sesuai selera teman-temannya, sedangkan harganya sudah wajar. Langkah perbaikan yang paling tepat adalah ....', 'none', '', '["menyesuaikan desain, warna, dan fungsi dengan selera target pasar, serta memperkuat promosi", "menurunkan harga di bawah modal agar produk kerajinan laku terjual banyak", "mengganti seluruh bahan dengan bahan impor", "menghentikan penjualan dan tidak membuat produk lagi"]'::jsonb, '[]'::jsonb, 'menyesuaikan desain, warna, dan fungsi dengan selera target pasar, serta memperkuat promosi', 10, 'Sesuai kunci jawaban.')
INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261115_08_50', 'PG', 'Prakarya 8', 'Saat kegiatan alternatif membuat mandala motif ornamen nusantara, Dito memetik daun dan bunga yang masih hidup dari pohon sekolah. Menurut prinsip kegiatan tersebut, penilaian terhadap tindakan Dito yang paling tepat adalah ....', 'none', '', '["benar, karena daun segar menghasilkan warna lebih bagus walaupun harus memanjat pohon", "salah, karena seharusnya memakai material alam yang sudah jatuh dan mati agar tidak mengganggu ekosistem", "benar, karena tumbuhan akan tumbuh kembali dengan cepat", "salah, karena mandala hanya boleh dibuat dengan bahan plastik"]'::jsonb, '[]'::jsonb, 'salah, karena seharusnya memakai material alam yang sudah jatuh dan mati agar tidak mengganggu ekosistem', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_01', 'PG', 'Bahasa Indonesia SMP 8', 'Teks tersebut termasuk jenis teks ....', 'none', '', '["Cerita fantasi", "Laporan hasil observasi", "Teks prosedur", "Teks persuasi"]'::jsonb, '[]'::jsonb, 'Laporan hasil observasi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_02', 'PG', 'Bahasa Indonesia SMP 8', 'Objek yang dibahas dalam teks tersebut adalah ....', 'none', '', '["Bunga mawar", "Bunga melati", "Bunga matahari", "Bunga anggrek"]'::jsonb, '[]'::jsonb, 'Bunga matahari', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_03', 'PG', 'Bahasa Indonesia SMP 8', 'Bagaimana bentuk daun bunga matahari berdasarkan teks?', 'none', '', '["Kecil dan bulat", "Lebar berbentuk hati", "Panjang dan runcing", "Tipis berbentuk jarum"]'::jsonb, '[]'::jsonb, 'Lebar berbentuk hati', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_04', 'PG', 'Bahasa Indonesia SMP 8', 'Mengapa bunga matahari membutuhkan cukup cahaya matahari?', 'none', '', '["Agar dapat tumbuh dengan baik", "Agar daunnya berubah warna", "Agar batangnya menjadi pendek", "Agar akarnya tidak tumbuh"]'::jsonb, '[]'::jsonb, 'Agar dapat tumbuh dengan baik', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_05', 'PG', 'Bahasa Indonesia SMP 8', 'Informasi yang sesuai dengan teks adalah ....<br>Teks 2 untuk soal nomor 6–10<br>Iklan Minuman Sehat<br>SEGARKAN HARIMU!<br>JUS BUAH ALAMI<br>Dibuat dari buah pilihan, tanpa tambahan pemanis buatan.<br>Sehat, Segar, dan Nikmat!<br>Ayo konsumsi buah setiap hari!', 'none', '', '["Bunga matahari hanya tumbuh di dalam ruangan.", "Biji bunga matahari dapat diolah menjadi kuaci.", "Bunga matahari memiliki bunga berwarna merah.", "Daun bunga matahari berbentuk panjang dan runcing."]'::jsonb, '[]'::jsonb, 'Biji bunga matahari dapat diolah menjadi kuaci.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_06', 'PG', 'Bahasa Indonesia SMP 8', 'Tujuan utama iklan tersebut adalah ....', 'none', '', '["Mengajak masyarakat mengonsumsi jus buah", "Memberitahukan cara menanam buah", "Menjelaskan proses pembuatan minuman", "Melaporkan hasil penelitian buah"]'::jsonb, '[]'::jsonb, 'Mengajak masyarakat mengonsumsi jus buah', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_07', 'PG', 'Bahasa Indonesia SMP 8', 'Kalimat yang menjadi slogan dalam iklan tersebut adalah ....', 'none', '', '["Dibuat dari buah pilihan", "Sehat, Segar, dan Nikmat!", "Ayo konsumsi buah setiap hari!", "Jus buah alami"]'::jsonb, '[]'::jsonb, 'Sehat, Segar, dan Nikmat!', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_08', 'PG', 'Bahasa Indonesia SMP 8', 'Keunggulan produk yang ditawarkan berdasarkan iklan adalah ....', 'none', '', '["Mengandung pewarna buatan", "Dibuat dari buah pilihan tanpa tambahan pemanis buatan", "Hanya tersedia dalam satu rasa", "Mengandung banyak bahan pengawet"]'::jsonb, '[]'::jsonb, 'Dibuat dari buah pilihan tanpa tambahan pemanis buatan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_09', 'PG', 'Bahasa Indonesia SMP 8', 'Sasaran utama iklan tersebut adalah ....', 'none', '', '["Orang yang ingin mengonsumsi minuman sehat", "Orang yang ingin membeli kendaraan", "Petani yang ingin menjual tanah", "Siswa yang ingin membeli buku"]'::jsonb, '[]'::jsonb, 'Orang yang ingin mengonsumsi minuman sehat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_10', 'PG', 'Bahasa Indonesia SMP 8', 'Jika iklan tersebut ingin dibuat lebih menarik, hal yang paling tepat dilakukan adalah ....<br>Teks 3 untuk soal nomor 11–15<br>Hutan Mangrove<br>Hutan mangrove merupakan ekosistem tumbuhan yang hidup di wilayah pesisir pantai. Tumbuhan mangrove memiliki akar yang khas dan mampu bertahan di lingkungan berlumpur serta air yang dipengaruhi pasang surut.<br>Hutan mangrove memiliki peran penting bagi lingkungan. Akar-akarnya dapat membantu mengurangi abrasi pantai dan menjadi tempat hidup berbagai jenis hewan, seperti ikan kecil, kepiting, dan udang.<br>Selain itu, hutan mangrove membantu menjaga keseimbangan ekosistem pesisir. Kerusakan hutan mangrove dapat menyebabkan berkurangnya habitat hewan dan meningkatnya risiko kerusakan pantai.', 'none', '', '["Menghilangkan nama produk", "Menggunakan gambar buah yang menarik dan informasi produk yang jelas", "Menggunakan tulisan yang sangat kecil", "Menghilangkan kalimat ajakan"]'::jsonb, '[]'::jsonb, 'Menggunakan gambar buah yang menarik dan informasi produk yang jelas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_11', 'PG', 'Bahasa Indonesia SMP 8', 'Hutan mangrove biasanya ditemukan di ....', 'none', '', '["Pegunungan tinggi", "Wilayah pesisir pantai", "Padang pasir", "Daerah perkotaan"]'::jsonb, '[]'::jsonb, 'Wilayah pesisir pantai', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_12', 'PG', 'Bahasa Indonesia SMP 8', 'Fungsi akar mangrove berdasarkan teks adalah ....', 'none', '', '["Menghasilkan buah yang manis", "Membantu mengurangi abrasi pantai", "Mengubah air laut menjadi air tawar", "Menghasilkan oksigen paling banyak di dunia"]'::jsonb, '[]'::jsonb, 'Membantu mengurangi abrasi pantai', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_13', 'PG', 'Bahasa Indonesia SMP 8', 'Hewan yang dapat hidup di kawasan hutan mangrove adalah ....', 'none', '', '["Harimau dan gajah", "Kambing dan sapi", "Ikan kecil, kepiting, dan udang", "Unta dan kuda"]'::jsonb, '[]'::jsonb, 'Ikan kecil, kepiting, dan udang', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_14', 'PG', 'Bahasa Indonesia SMP 8', 'Apa kemungkinan yang terjadi jika hutan mangrove mengalami kerusakan?', 'none', '', '["Habitat hewan semakin bertambah", "Risiko kerusakan pantai meningkat", "Air laut menjadi lebih jernih", "Semua hewan berpindah ke pegunungan"]'::jsonb, '[]'::jsonb, 'Risiko kerusakan pantai meningkat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_15', 'PG', 'Bahasa Indonesia SMP 8', 'Gagasan utama paragraf kedua adalah ....<br>Teks 4 untuk soal nomor 16–20', 'image', './assets/soal/soal-0043.jpg', '["Bentuk akar tumbuhan mangrove", "Jenis tanah di wilayah pesisir", "Peran hutan mangrove bagi lingkungan", "Cara menanam pohon mangrove"]'::jsonb, '[]'::jsonb, 'Peran hutan mangrove bagi lingkungan', 10, 'Sesuai kunci jawaban.'),
