  ('Q_20261117_08_34', 'PG', 'Bahasa Indonesia SMP 8', 'Bagian teks LHO yang menjelaskan ciri-ciri atau bagian-bagian objek disebut ....', 'none', '', '["Deskripsi bagian", "Orientasi", "Komplikasi", "Resolusi"]'::jsonb, '[]'::jsonb, 'Deskripsi bagian', 10, 'Sesuai kunci jawaban.'),
