  ('Q_20261117_08_46', 'PG', 'Bahasa Indonesia SMP 8', 'Perbedaan iklan dan slogan yang tepat adalah ....', 'none', '', '["Iklan berisi penawaran atau informasi, sedangkan slogan berupa kalimat singkat yang mudah diingat.", "Iklan hanya menggunakan gambar, sedangkan slogan hanya menggunakan angka.", "Iklan selalu panjang, sedangkan slogan selalu berbentuk paragraf.", "Iklan dan slogan tidak memiliki perbedaan."]'::jsonb, '[]'::jsonb, 'Iklan berisi penawaran atau informasi, sedangkan slogan berupa kalimat singkat yang mudah diingat.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_47', 'PG', 'Bahasa Indonesia SMP 8', 'Berikut ini yang merupakan contoh kalimat persuasif adalah ....', 'none', '', '["Sampah terdiri atas sampah organik dan anorganik.", "Ayo, buanglah sampah pada tempatnya!", "Sungai mengalir dari hulu ke hilir.", "Bumi merupakan tempat tinggal manusia."]'::jsonb, '[]'::jsonb, 'Ayo, buanglah sampah pada tempatnya!', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_48', 'PG', 'Bahasa Indonesia SMP 8', 'Perhatikan slogan berikut!<br>&quot;Buku adalah Jendela Dunia.&quot;<br>Makna slogan tersebut adalah ....', 'none', '', '["Buku digunakan untuk melihat pemandangan", "Membaca buku dapat menambah pengetahuan dan wawasan", "Buku harus selalu dibawa ke mana saja", "Buku hanya digunakan oleh pelajar"]'::jsonb, '[]'::jsonb, 'Membaca buku dapat menambah pengetahuan dan wawasan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_49', 'PG', 'Bahasa Indonesia SMP 8', 'Jika ingin membuat poster tentang bahaya narkoba, kalimat yang paling tepat adalah ....', 'none', '', '["Narkoba Membuat Hidup Lebih Menarik!", "Nikmati Hidup Tanpa Aturan!", "Katakan Tidak pada Narkoba, Selamatkan Masa Depan!", "Cobalah Sesuatu yang Baru!"]'::jsonb, '[]'::jsonb, 'Katakan Tidak pada Narkoba, Selamatkan Masa Depan!', 10, 'Sesuai kunci jawaban.')
