  ('Q_20261117_08_50', 'PG', 'Bahasa Indonesia SMP 8', 'Perbedaan utama teks LHO dengan iklan, slogan, dan poster adalah ....', 'none', '', '["Teks LHO menyajikan informasi berdasarkan hasil pengamatan, sedangkan iklan, slogan, dan poster umumnya bertujuan menyampaikan pesan atau memengaruhi pembaca.", "Teks LHO selalu berisi ajakan, sedangkan iklan selalu berisi fakta ilmiah.", "Teks LHO hanya menggunakan gambar, sedangkan poster hanya menggunakan tulisan.", "Semua jenis teks tersebut memiliki tujuan dan struktur yang sama."]'::jsonb, '[]'::jsonb, 'Teks LHO menyajikan informasi berdasarkan hasil pengamatan, sedangkan iklan, slogan, dan poster umumnya bertujuan menyampaikan pesan atau memengaruhi pembaca.', 10, 'Sesuai kunci jawaban.'),
