  ('Q_20261119_08_36', 'PG', 'Pendidikan Pancasila SMP 8', 'Pasal 27 ayat 1 UUD NRI Tahun 1945 menyatakan bahwa segala warga negara bersamaan kedudukannya di dalam hukum dan pemerintahan dan wajib menjunjung hukum. Artinya...', 'none', '', '["Pejabat boleh melanggar hukum", "Semua warga negara sama di depan hukum", "Hukum hanya untuk rakyat miskin", "Warga negara bebas melanggar hukum"]'::jsonb, '[]'::jsonb, 'Semua warga negara sama di depan hukum', 10, 'Sesuai kunci jawaban.'),
