  ('Q_20261119_08_39', 'PG', 'Pendidikan Pancasila SMP 8', 'Cara yang benar dalam mengeluarkan pendapat di kelas adalah...', 'none', '', '["Berteriak dan memotong pembicaraan guru", "Mengangkat tangan, berbicara sopan, dan menghargai pendapat orang lain", "Mengejek pendapat teman", "Memaksakan pendapat sendiri agar diterima"]'::jsonb, '[]'::jsonb, 'Mengangkat tangan, berbicara sopan, dan menghargai pendapat orang lain', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261119_08_40', 'PG', 'Pendidikan Pancasila SMP 8', 'Jika pendapat kita berbeda dengan teman saat musyawarah, sikap yang sesuai Pancasila adalah...', 'none', '', '["Marah dan meninggalkan musyawarah", "Tetap menghargai pendapat teman dan mencari mufakat", "Mengancam teman", "Tidak mau lagi bermusyawarah"]'::jsonb, '[]'::jsonb, 'Tetap menghargai pendapat teman dan mencari mufakat', 10, 'Sesuai kunci jawaban.'),
