  ('Q_20261119_08_43', 'PG', 'Pendidikan Pancasila SMP 8', 'Seorang siswa menyampaikan usul agar jadwal piket kelas diperbaiki. Sikap ini menunjukkan...', 'none', '', '["Berani mengeluarkan pendapat untuk kebaikan bersama", "Melawan guru", "Suka mencari masalah", "Tidak taat aturan"]'::jsonb, '[]'::jsonb, 'Berani mengeluarkan pendapat untuk kebaikan bersama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261119_08_44', 'PG', 'Pendidikan Pancasila SMP 8', 'Jika kita tidak setuju dengan peraturan sekolah, tindakan yang sesuai Pancasila adalah...', 'none', '', '["Melanggar peraturan tersebut diam-diam", "Menyampaikan keberatan melalui OSIS atau musyawarah dengan sopan", "Mengajak teman demo anarkis", "Tidak masuk sekolah"]'::jsonb, '[]'::jsonb, 'Menyampaikan keberatan melalui OSIS atau musyawarah dengan sopan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261119_08_45', 'PG', 'Pendidikan Pancasila SMP 8', 'Nilai Pancasila yang paling menonjol dalam kegiatan musyawarah adalah sila ke...', 'none', '', '["1", "2", "3", "4"]'::jsonb, '[]'::jsonb, '4', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261119_08_46', 'PG', 'Pendidikan Pancasila SMP 8', 'Nilai Pancasila yang paling menonjol dalam kegiatan bakti sosial membantu korban bencana adalah sila ke...', 'none', '', '["1", "2", "3", "5"]'::jsonb, '[]'::jsonb, '2', 10, 'Sesuai kunci jawaban.'),
