INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261119_08_50', 'PG', 'Pendidikan Pancasila SMP 8', 'Sikap terbaik sebagai pelajar dalam mengamalkan Pancasila di era digital adalah...', 'none', '', '["Menyaring informasi, tidak menyebarkan hoaks, dan menggunakan media sosial secara santun", "Mengikuti semua tren luar negeri tanpa saringan", "Tidak menggunakan internet sama sekali", "Membully teman di media sosial"]'::jsonb, '[]'::jsonb, 'Menyaring informasi, tidak menyebarkan hoaks, dan menggunakan media sosial secara santun', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_01', 'PG', 'IPA SMP 9', 'Di dalam inti sel makhluk hidup terdapat molekul pembawa informasi genetik yang berbentuk untai ganda berpilin (<i>double helix</i>) dan tersusun atas gugus fosfat, gula deoksiribosa, serta basa nitrogen. Molekul yang dimaksud adalah .... <i>[LOTS - C1]</i>', 'none', '', '["RNA (Ribonucleic Acid)", "DNA (Deoxyribonucleic Acid)", "Sentromer", "Ribosom"]'::jsonb, '[]'::jsonb, 'DNA (Deoxyribonucleic Acid)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_02', 'PG', 'IPA SMP 9', 'Seorang murid mengamati tanaman bunga mawar di halaman sekolah yang memiliki kelopak berwarna merah cerah. Sifat warna merah yang tampak dan dapat diamati secara langsung oleh indra disebut .... <i>[LOTS - C2]</i>', 'none', '', '["Genotipe", "Fenotipe", "Alel resesif", "Kromosom homolog"]'::jsonb, '[]'::jsonb, 'Fenotipe', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_03', 'PG', 'IPA SMP 9', 'Kelainan genetik pada manusia yang diwariskan melalui kromosom seks (gonosom) X sehingga penderitanya mengalami gangguan pembekuan darah saat terluka adalah .... <i>[LOTS - C1]</i>', 'none', '', '["Albino", "Talasemia", "Hemofilia", "Polidaktili"]'::jsonb, '[]'::jsonb, 'Hemofilia', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_04', 'PG', 'IPA SMP 9', 'Tanaman kacang kapri berbiji bulat (BB) disilangkan dengan kacang kapri berbiji kisut (bb). Sifat bulat dominan penuh terhadap kisut. Jika keturunan pertama (F1) disilangkan sesamanya dan menghasilkan 160 tanaman F2, jumlah tanaman F2 yang diperkirakan berbiji kisut adalah .... <i>[MOTS - C3]</i>', 'none', '', '["40 tanaman", "80 tanaman", "120 tanaman", "160 tanaman"]'::jsonb, '[]'::jsonb, '40 tanaman', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_05', 'PG', 'IPA SMP 9', 'Persilangan antara bunga pukul empat (<i>Mirabilis </i><i>jalapa</i>) warna merah (MM) dengan warna putih (mm) menghasilkan keturunan F1 berwarna merah muda (Mm) karena sifat intermediet. Jika F1 disilangkan dengan induknya yang berwarna putih (mm), persentase keturunan yang memiliki fenotipe merah muda adalah .... <i>[MOTS - C3]</i>', 'none', '', '["25%", "50%", "75%", "100%"]'::jsonb, '[]'::jsonb, '50%', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_06', 'PG', 'IPA SMP 9', 'Sepasang suami istri memiliki golongan darah masing-masing A heterozigot (IAi) dan B heterozigot (IBi). Kemungkinan golongan darah yang dapat dimiliki oleh anak-anak mereka adalah .... <i>[MOTS - C3]</i>', 'none', '', '["Hanya golongan darah A dan B", "Hanya golongan darah AB dan O", "Golongan darah A, B, dan AB", "Golongan darah A, B, AB, dan O"]'::jsonb, '[]'::jsonb, 'Golongan darah A, B, AB, dan O', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_07', 'PG', 'IPA SMP 9', 'Tanaman mangga berbatang tinggi buah manis memiliki genotipe heterozigot ganda (TtMm). Macam gamet yang dapat dibentuk oleh tanaman mangga tersebut sesuai Hukum II Mendel adalah .... <i>[MOTS - C3]</i>', 'none', '', '["TM dan tm", "Tt dan Mm", "TM, Tm, tM, dan tm", "TT, tt, MM, dan mm"]'::jsonb, '[]'::jsonb, 'TM, Tm, tM, dan tm', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_08', 'PG', 'IPA SMP 9', 'Seorang perempuan pembawa sifat (<i>carrier</i>) buta warna (X<sup>CB</sup>X<sup>cb</sup>) menikah dengan seorang laki-laki bermata normal (X<sup>CB</sup>Y). Berapa peluang pasangan tersebut memperoleh anak laki-laki yang menderita buta warna dari seluruh kemungkinan keturunannya? <i>[MOTS - C3]</i>', 'none', '', '["25%", "50%", "75%", "100%"]'::jsonb, '[]'::jsonb, '25%', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_09', 'PG', 'IPA SMP 9', 'Pak Budi ingin memilih satu tanaman dari generasi F2 yang jika ditanam dan dibiarkan menyerbuk sendiri akan selalu menghasilkan keturunan berbuah besar dan manis (galur murni) tanpa pernah memunculkan sifat buah kecil atau kurang manis. Genotipe tanaman F2 yang harus dipilih Pak Budi beserta peluang kemunculannya di F2 adalah .... <i>[HOTS - C4]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 10<br>Perhatikan data silsilah keluarga terkait kelainan hemofilia (terpaut kromosom X resesif, Xh) berikut:<br>• Generasi I: Ayah (1) normal menikah dengan Ibu (2) normal.<br>• Generasi II: Mereka memiliki 3 anak: Anak laki-laki (3) menderita hemofilia, Anak perempuan (4) normal, dan Anak laki-laki (5) normal.<br>• Anak perempuan (4) menikah dengan laki-laki normal (6) dan memiliki seorang anak laki-laki (7) yang menderita hemofilia.</th></tr></table>', 'none', '', '["BbMm dengan peluang 4/16", "BBMM dengan peluang 1/16", "BBMm dengan peluang 2/16", "BbMM dengan peluang 2/16"]'::jsonb, '[]'::jsonb, 'BBMM dengan peluang 1/16', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_10', 'ESAI', 'IPA SMP 9', 'Berdasarkan analisis peta silsilah di atas, pernyataan evaluasi genetik manakah yang tepat? (Pilih 2 jawaban benar) <i>[HOTS - C5 (</i><i>Pilihan</i><i> Ganda </i><i>Kompleks</i><i> — </i><i>Pilih</i><i> DUA </i><i>jawaban</i><i> yang </i><i>benar</i><i>)]</i><br>[  ] A. Ibu (2) pada Generasi I dipastikan memiliki genotipe pembawa sifat (carrier) XHXh.<br>[  ] B. Ayah (1) mewariskan kromosom Xh kepada anak laki-laki (3) sehingga menderita hemofilia.<br>[  ] C. Anak perempuan (4) pada Generasi II memiliki genotipe XHXh.<br>[  ] D. Anak laki-laki (5) berpeluang 50% mewariskan gen hemofilia kepada anak perempuannya kelak.', 'none', '', '[]'::jsonb, '[]'::jsonb, 'A dan C', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_11', 'PG', 'IPA SMP 9', 'Berdasarkan data hasil percobaan tersebut, analisis yang paling logis mengenai genotipe induk berbunga ungu batang tinggi yang sebenarnya digunakan murid adalah .... <i>[HOTS - C4]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 12<br>Di sebuah klinik bersalin terjadi kekeliruan penempatan gelang identitas dua bayi laki-laki yang lahir pada jam yang sama. Tim medis melakukan pemeriksaan golongan darah dan sifat lesung pipi (gen L dominan memunculkan lesung pipi, gen l resesif tidak berlesung pipi) untuk memastikan orang tua biologis masing-masing bayi:<br>• Bayi X: Golongan darah O, tidak memiliki lesung pipi.<br>• Bayi Y: Golongan darah AB, memiliki lesung pipi.<br>• Pasangan Keluarga 1: Suami bergolongan darah A (berlesung pipi), Istri bergolongan darah B (tidak berlesung pipi).<br>• Pasangan Keluarga 2: Suami bergolongan darah AB (berlesung pipi), Istri bergolongan darah O (berlesung pipi).</th></tr></table>', 'none', '', '["UUTT, karena seluruh keturunan memiliki sifat dominan penuh", "UuTT, karena semua keturunan berbatang tinggi", "UUTt, karena sifat warna ungu selalu muncul (100%) sedangkan tinggi batang terpisah 1 : 1", "uutt, karena terjadi mutasi spontan pada saat penyerbukan"]'::jsonb, '[]'::jsonb, 'UUTt, karena sifat warna ungu selalu muncul (100%) sedangkan tinggi batang terpisah 1 : 1', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_12', 'ESAI', 'IPA SMP 9', 'Berdasarkan prinsip pewarisan sifat golongan darah sistem ABO dan sifat lesung pipi, kesimpulan evaluasi yang sahih adalah .... (Pilih 2 jawaban benar) <i>[HOTS - C5 (</i><i>Pilihan</i><i> Ganda </i><i>Kompleks</i><i> — </i><i>Pilih</i><i> DUA </i><i>jawaban</i><i> yang </i><i>benar</i><i>)]</i><br>[  ] A. Bayi X adalah anak biologis dari Pasangan Keluarga 1 dengan syarat kedua orang tuanya bergenotipe golongan darah heterozigot (IAi dan IBi).<br>[  ] B. Bayi X tidak mungkin merupakan anak biologis dari Pasangan Keluarga 2 karena individu bergolongan darah AB tidak memiliki alel i.<br>[  ] C. Bayi Y adalah anak biologis dari Pasangan Keluarga 2 karena ibunya bergolongan darah O.<br>[  ] D. Pasangan Keluarga 1 tidak mungkin memiliki anak bergolongan darah O maupun AB.', 'none', '', '[]'::jsonb, '[]'::jsonb, 'A dan B', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_13', 'ESAI', 'IPA SMP 9', 'Seorang peternak memiliki dua jenis sapi lokal: Sapi Jantan Bali bertubuh besar tetapi tahan penyakit rendah (BBtt) dan Sapi Betina Madura bertubuh sedang tetapi daya tahan penyakit tinggi (bbTT). Gen B (tubuh besar) dominan terhadap b (tubuh sedang), dan gen T (tahan penyakit tinggi) dominan terhadap t (tahan penyakit rendah). Rancanglah skema persilangan hingga generasi F2 beserta cara menyeleksi individu F2 agar peternak memperoleh bibit sapi galur murni bertubuh besar dan tahan penyakit tinggi! <i>[HOTS - C6]</i>', 'none', '', '[]'::jsonb, '[]'::jsonb, 'Uraian (Rubrik)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_14', 'PG', 'IPA SMP 9', 'Di dalam ekosistem kebun, burung jalak sering hinggap di punggung kerbau untuk memakan kutu yang menempel pada kulit kerbau. Kerbau merasa terbantu karena kutunya berkurang, sedangkan burung jalak memperoleh makanan. Pola interaksi ini disebut .... <i>[LOTS - C1]</i>', 'none', '', '["Komensalisme", "Mutualisme", "Parasitisme", "Kompetisi interspesifik"]'::jsonb, '[]'::jsonb, 'Mutualisme', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_15', 'PG', 'IPA SMP 9', 'Efek rumah kaca sebenarnya merupakan proses alami yang bermanfaat menjaga suhu bumi tetap hangat sehingga layak dihuni makhluk hidup. Gas-gas atmosfer berikut yang berperan menahan pantulan radiasi panas matahari (inframerah) dari permukaan bumi adalah .... <i>[LOTS - C2]</i>', 'none', '', '["Oksigen (O<sub>2</sub>) dan Nitrogen (N<sub>2</sub>)", "Karbon dioksida (CO<sub>2</sub>) dan Metana (CH<sub>4</sub>)", "Argon (Ar) dan Helium (He)", "Hidrogen (H<sub>2</sub>) dan Neon (Ne)"]'::jsonb, '[]'::jsonb, 'Karbon dioksida (CO<sub>2</sub>) dan Metana (CH<sub>4</sub>)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_16', 'PG', 'IPA SMP 9', 'Sektor transportasi menyumbang emisi karbon dioksida (CO<sub>2</sub>) yang signifikan di wilayah perkotaan. Penyebab utama meningkatnya emisi CO<sub>2</sub> dari kendaraan bermotor konvensional adalah .... <i>[LOTS - C2]</i>', 'none', '', '["Penggunaan ban karet sintetis pada jalan aspal", "Pembakaran bahan bakar fosil (bensin dan solar) pada mesin kendaraan", "Pendingin udara (AC) mobil yang mengeluarkan uap air", "Gesekan antara bodi kendaraan dengan udara atmosfer"]'::jsonb, '[]'::jsonb, 'Pembakaran bahan bakar fosil (bensin dan solar) pada mesin kendaraan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_17', 'PG', 'IPA SMP 9', 'Pada ekosistem sawah terdapat rantai makanan: Padi -&gt; Tikus -&gt; Ular -&gt; Elang. Apabila petani melakukan perburuan ular secara besar-besaran untuk diambil kulitnya, dampak langsung yang akan terjadi pada keseimbangan ekosistem sawah tersebut adalah .... <i>[MOTS - C3]</i>', 'none', '', '["Populasi padi meningkat pesat karena tidak ada hama", "Populasi tikus meningkat drastis sehingga hasil panen padi menurun", "Populasi elang meningkat karena mendapat sumber makanan baru", "Populasi tikus menurun karena kehilangan predator alaminya"]'::jsonb, '[]'::jsonb, 'Populasi tikus meningkat drastis sehingga hasil panen padi menurun', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_18', 'PG', 'IPA SMP 9', 'Jarak rumah Rina ke sekolah adalah 4 km (8 km pulang-pergi). Jika menggunakan sepeda motor, emisi karbon yang dihasilkan rata-rata sebesar 120 gram CO<sub>2</sub> per km. Apabila Rina memutuskan bersepeda ke sekolah selama 5 hari efektif dalam seminggu, total emisi karbon yang berhasil ia kurangi dalam seminggu adalah .... <i>[MOTS - C3]</i>', 'none', '', '["960 gram CO<sub>2</sub>", "2.400 gram CO<sub>2</sub>", "4.800 gram CO<sub>2</sub>", "6.000 gram CO<sub>2</sub>"]'::jsonb, '[]'::jsonb, '4.800 gram CO<sub>2</sub>', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_19', 'PG', 'IPA SMP 9', 'Ekosistem hutan mangrove di wilayah pesisir Indonesia dikenal sebagai penyimpan &#x27;karbon biru&#x27; (blue carbon) yang sangat efektif dalam memitigasi perubahan iklim karena .... <i>[MOTS - C3]</i>', 'none', '', '["Daun mangrove memantulkan seluruh cahaya matahari kembali ke luar angkasa", "Akar dan sedimen lumpur mangrove mampu menyerap serta menyimpan karbon dalam jumlah besar dan jangka waktu lama", "Air laut di sekitar mangrove melarutkan seluruh gas metana di udara", "Pohon mangrove tidak melakukan proses respirasi pada malam hari"]'::jsonb, '[]'::jsonb, 'Akar dan sedimen lumpur mangrove mampu menyerap serta menyimpan karbon dalam jumlah besar dan jangka waktu lama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_20', 'PG', 'IPA SMP 9', 'Dalam sebuah piramida energi ekosistem padang rumput, produsen (rumput) menangkap energi cahaya matahari dan menghasilkan energi kimia sebesar 25.000 kkal. Jika efisiensi transfer energi antar tingkat trofik mengikuti aturan 10%, energi yang diterima oleh konsumen tingkat II (ular) adalah sebesar .... <i>[MOTS - C3]</i>', 'none', '', '["2.500 kkal", "250 kkal", "25 kkal", "2,5 kkal"]'::jsonb, '[]'::jsonb, '250 kkal', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_21', 'PG', 'IPA SMP 9', 'Perubahan iklim memicu naiknya permukaan air laut yang mengancam permukiman warga di daerah pesisir pantai utara Jawa. Bentuk tindakan adaptasi yang paling tepat dilakukan masyarakat pesisir untuk menghadapi dampak tersebut adalah .... <i>[MOTS - C3]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 22<br>Data pemantauan iklim menunjukkan bahwa sejak tahun 1975 hingga 2025, konsentrasi rata-rata karbon dioksida (CO2) global meningkat dari 331 ppm menjadi lebih dari 424 ppm. Pada periode yang sama, suhu permukaan laut tropis meningkat sekitar 0,8 °C hingga 1,1 °C. Para ahli kelautan mencatat bahwa peningkatan suhu air laut memicu peristiwa pemutihan karang (coral bleaching), yaitu keluarnya alga mikroskopis (Zooxanthellae) yang hidup bersimbiosis di dalam jaringan terumbu karang.</th></tr></table>', 'none', '', '["Mengganti seluruh kendaraan bermotor dengan sepeda listrik", "Membangun rumah panggung yang tahan genangan rob dan melakukan rehabilitasi sabuk hijau mangrove", "Membuang sampah plastik ke muara sungai agar membentuk tanggul alami", "Menghentikan seluruh kegiatan penangkapan ikan di laut lepas"]'::jsonb, '[]'::jsonb, 'Membangun rumah panggung yang tahan genangan rob dan melakukan rehabilitasi sabuk hijau mangrove', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_22', 'PG', 'IPA SMP 9', 'Berdasarkan hubungan simbiosis dan data iklim pada wacana tersebut, analisis dampak lanjutan yang paling tepat apabila peristiwa pemutihan terumbu karang berlangsung dalam jangka panjang adalah .... <i>[HOTS - C4]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 23<br>Lahan gambut tropis menyimpan cadangan karbon di bawah permukaan tanah yang jauh lebih besar dibandingkan hutan mineral biasa karena kondisi tanahnya yang jenuh air menghambat dekomposisi bahan organik. Untuk membuka lahan perkebunan monokultur skala luas, sering dilakukan pengeringan lahan gambut dengan membuat kanal-kanal drainase serta pembakaran lahan.</th></tr></table>', 'none', '', '["Terumbu karang akan tumbuh lebih cepat karena tidak perlu berbagi nutrisi dengan alga", "Terumbu karang kehilangan sumber energi utama hasil fotosintesis alga sehingga mati dan merusak habitat berbagai spesies ikan", "Populasi ikan karang meningkat drastis karena air laut menjadi lebih hangat dan jernih", "Kadar oksigen terlarut di perairan dangkal meningkat tajam akibat hilangnya Zooxanthellae"]'::jsonb, '[]'::jsonb, 'Terumbu karang kehilangan sumber energi utama hasil fotosintesis alga sehingga mati dan merusak habitat berbagai spesies ikan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_23', 'ESAI', 'IPA SMP 9', 'Evaluasilah dampak ekologis dan klimatologis yang timbul akibat pengeringan dan pembakaran lahan gambut tersebut! (Pilih 2 jawaban benar) <i>[HOTS - C5 (</i><i>Pilihan</i><i> Ganda </i><i>Kompleks</i><i> — </i><i>Pilih</i><i> DUA </i><i>jawaban</i><i> yang </i><i>benar</i><i>)]</i><br>[  ] A. Pengeringan gambut membuat bahan organik terpapar oksigen sehingga mempercepat dekomposisi aerobik dan melepaskan CO<sub>2</sub> dalam jumlah masif.<br>[  ] B. Pembakaran lahan gambut meningkatkan kesuburan tanah secara permanen dan mencegah kebakaran di musim kemarau berikutnya.<br>[  ] C. Hilangnya keanekaragaman hayati asli hutan rawa gambut yang digantikan oleh satu jenis tanaman monokultur yang rentan terhadap hama.<br>[  ] D. Kanal drainase meningkatkan cadangan air tanah di musim kemarau sehingga kelembapan udara tetap terjaga.<br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 24<br>Sebuah SMP menghasilkan rata-rata 60 kg sampah per hari yang terdiri atas 65% sisa makanan dan dedaunan (organik), 25% plastik dan kertas, serta 10% residu lainnya. Selama ini, seluruh sampah tersebut diangkut tanpa pemilahan dan ditumpuk menggunung di Tempat Pemrosesan Akhir (TPA) sistem terbuka (open dumping).</th></tr></table>', 'none', '', '[]'::jsonb, '[]'::jsonb, 'A dan C', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_24', 'PG', 'IPA SMP 9', 'Mengapa penumpukan 65% sampah organik sekolah di TPA terbuka tanpa pengelolaan justru memperparah laju pemanasan global dibandingkan jika sampah tersebut diolah menjadi kompos di sekolah? <i>[HOTS - C4]</i>', 'none', '', '["Sampah organik di TPA terbuka akan terurai secara anaerob (tanpa oksigen) dan menghasilkan gas metana (CH<sub>4</sub>) yang daya tangkap panasnya jauh lebih kuat daripada CO<sub>2</sub>", "Sampah organik di TPA terbuka menyerap seluruh gas oksigen di atmosfer sehingga suhu udara naik", "Proses pengomposan di sekolah menghasilkan gas freon (CFC) yang mampu menambal lapisan ozon", "Tumpukan sampah plastik di TPA menghalangi sampah organik terkena sinar matahari langsung"]'::jsonb, '[]'::jsonb, 'Sampah organik di TPA terbuka akan terurai secara anaerob (tanpa oksigen) dan menghasilkan gas metana (CH<sub>4</sub>) yang daya tangkap panasnya jauh lebih kuat daripada CO<sub>2</sub>', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_25', 'ESAI', 'IPA SMP 9', 'Jika ditinjau dari prinsip ekologi dan keberlanjutan mitigasi perubahan iklim jangka panjang, keunggulan Proposal 2 dibandingkan Proposal 1 adalah .... (Pilih 2 jawaban benar) <i>[HOTS - C5 (</i><i>Pilihan</i><i> Ganda </i><i>Kompleks</i><i> — </i><i>Pilih</i><i> DUA </i><i>jawaban</i><i> yang </i><i>benar</i><i>)]</i><br>[  ] A. Struktur vegetasi berlapis (multistrata) memaksimalkan penyerapan CO<sub>2</sub> pada berbagai ketinggian tajuk serta menurunkan suhu mikro lebih efektif.<br>[  ] B. Proposal 1 lebih tahan terhadap serangan wabah hama dan penyakit tanaman dibandingkan Proposal 2.<br>[  ] C. Keanekaragaman jenis tumbuhan pada Proposal 2 mendukung terbentuknya jaring-jaring makanan yang stabil bagi burung dan serangga penyerbuk.<br>[  ] D. Proposal 2 tidak memerlukan air sama sekali pada masa awal penanaman karena pohon lokal tidak berfotosintesis.', 'none', '', '[]'::jsonb, '[]'::jsonb, 'A dan C', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_26', 'ESAI', 'IPA SMP 9', 'Desa Sukamaju merupakan wilayah pertanian padi yang dalam tiga tahun terakhir mengalami pergeseran musim hujan, kekeringan saat fase pengisian bulir padi, serta ledakan populasi hama wereng cokelat akibat hilangnya habitat burung pemakan serangga dan katak sawah. Rancanglah 3 langkah solusi terpadu yang menggabungkan prinsip pemulihan interaksi ekosistem (pengendalian hayati) dan upaya mitigasi/adaptasi perubahan iklim di desa tersebut! <i>[HOTS - C6]</i>', 'none', '', '[]'::jsonb, '[]'::jsonb, 'Uraian (Rubrik)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_27', 'PG', 'IPA SMP 9', 'Penerapan bioteknologi telah dilakukan masyarakat sejak ribuan tahun lalu untuk mengolah bahan pangan. Ciri khas utama dari bioteknologi konvensional adalah .... <i>[LOTS - C1]</i>', 'none', '', '["Memanfaatkan mikroorganisme secara langsung melalui proses fermentasi dengan peralatan sederhana", "Melakukan rekayasa genetika dengan menyisipkan gen asing ke dalam DNA organisme", "Menggunakan teknik kultur jaringan di laboratorium steril berteknologi tinggi", "Menghasilkan organisme transgenik yang memiliki sifat baru di luar spesiesnya"]'::jsonb, '[]'::jsonb, 'Memanfaatkan mikroorganisme secara langsung melalui proses fermentasi dengan peralatan sederhana', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_28', 'PG', 'IPA SMP 9', 'Pasangan yang paling tepat antara produk bioteknologi konvensional dengan jenis mikroorganisme yang berperan dalam proses pembuatannya adalah .... <i>[LOTS - C1]</i>', 'none', '', '["Tempe — <i>Saccharomyces cerevisiae</i>", "Tapai singkong — <i>Rhizopus oryzae</i>", "Yoghurt — <i>Lactobacillus bulgaricus</i>", "Nata de coco — <i>Aspergillus </i><i>wentii</i>"]'::jsonb, '[]'::jsonb, 'Yoghurt — <i>Lactobacillus bulgaricus</i>', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_29', 'PG', 'IPA SMP 9', 'Pada proses pembuatan roti manis, ragi (Saccharomyces cerevisiae) dicampurkan ke dalam adonan tepung terigu dan didiamkan selama beberapa saat sebelum dipanggang. Adonan roti dapat mengembang karena aktivitas ragi menghasilkan .... <i>[LOTS - C2]</i>', 'none', '', '["Gas oksigen yang terperangkap di dalam jaringan gluten", "Gas karbon dioksida (CO<sub>2</sub>) dari proses fermentasi alkohol", "Asam laktat yang melunakkan butiran gula pasir", "Enzim selulase yang memecah protein tepung terigu"]'::jsonb, '[]'::jsonb, 'Gas karbon dioksida (CO<sub>2</sub>) dari proses fermentasi alkohol', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_30', 'PG', 'IPA SMP 9', 'Nata de coco merupakan produk pangan kenyal yang terbuat dari air kelapa melalui bantuan bakteri <i>Acetobacter </i><i>xylinum</i>. Bakteri tersebut mengubah gula dalam air kelapa menjadi lapisan serat padat berupa .... <i>[LOTS - C2]</i>', 'none', '', '["Amilum (pati)", "Selulosa bakterial", "Protein kasein", "Asam lemak jenuh"]'::jsonb, '[]'::jsonb, 'Selulosa bakterial', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_31', 'PG', 'IPA SMP 9', 'Dalam pembuatan yoghurt, susu segar dipasteurisasi terlebih dahulu lalu diinokulasi dengan starter bakteri asam laktat. Perubahan rasa susu menjadi asam dan teksturnya menjadi kental terjadi karena bakteri mengubah laktosa susu menjadi .... <i>[MOTS - C3]</i>', 'none', '', '["Alkohol dan gas karbon dioksida sehingga protein susu larut", "Asam laktat yang menurunkan pH sehingga protein susu (kasein) menggumpal (koagulasi)", "Asam asetat yang menguapkan seluruh kandungan air dalam susu", "Glukosa sederhana yang mengikat lemak susu menjadi padat"]'::jsonb, '[]'::jsonb, 'Asam laktat yang menurunkan pH sehingga protein susu (kasein) menggumpal (koagulasi)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_32', 'PG', 'IPA SMP 9', 'Pada proses pembuatan tempe kedelai, setelah kedelai direbus dan dikupas kulit arinya, kedelai harus ditiriskan dan didinginkan terlebih dahulu sebelum ditaburi ragi tempe (<i>Rhizopus oryzae</i>). Tujuan utama tahapan pendinginan kedelai tersebut adalah .... <i>[MOTS - C3]</i>', 'none', '', '["Agar air di permukaan kedelai menguap dan suhu tinggi tidak mematikan spora jamur pada ragi", "Supaya kulit ari kedelai menempel kembali pada keping biji", "Untuk menghentikan kerja enzim pemecah protein pada biji kedelai", "Agar bakteri pembusuk tumbuh lebih cepat sebelum jamur berkembang"]'::jsonb, '[]'::jsonb, 'Agar air di permukaan kedelai menguap dan suhu tinggi tidak mematikan spora jamur pada ragi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_33', 'PG', 'IPA SMP 9', 'Dalam pembuatan asinan sayur (fermentasi sawi hijau/kubis), penambahan garam dapur (NaCl) sekitar 2–3% dari berat sayuran berfungsi penting untuk .... <i>[MOTS - C3]</i>', 'none', '', '["Memberikan warna hijau cerah permanen pada daun sayuran", "Menghambat pertumbuhan bakteri pembusuk dan memberi kondisi selektif bagi bakteri asam laktat alami", "Membunuh seluruh mikroorganisme tanpa terkecuali agar sayuran steril", "Mengubah selulosa daun menjadi alkohol dalam waktu satu jam"]'::jsonb, '[]'::jsonb, 'Menghambat pertumbuhan bakteri pembusuk dan memberi kondisi selektif bagi bakteri asam laktat alami', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_34', 'PG', 'IPA SMP 9', 'Tempe memiliki nilai cerna protein yang lebih tinggi dibandingkan kedelai rebus biasa sehingga sangat baik dikonsumsi oleh anak-anak maupun lansia. Hal ini terjadi karena selama fermentasi tempe, jamur <i>Rhizopus sp</i>. menghasilkan enzim protease yang .... <i>[MOTS - C3]</i>', 'none', '', '["Mengubah seluruh protein kedelai menjadi lemak tak jenuh", "Memecah protein kompleks kedelai menjadi asam-asam amino yang lebih sederhana dan mudah diserap tubuh", "Mengikat zat besi sehingga tidak larut dalam sistem pencernaan", "Meningkatkan kadar asam fitat penghambat penyerapan nutrisi"]'::jsonb, '[]'::jsonb, 'Memecah protein kompleks kedelai menjadi asam-asam amino yang lebih sederhana dan mudah diserap tubuh', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_35', 'PG', 'IPA SMP 9', 'Kelompok karya ilmiah remaja SMP membuat cairan serbaguna eco-enzyme menggunakan perbandingan standar 1 bagian molase (gula merah), 3 bagian limbah kulit buah/sayur segar, dan 10 bagian air di dalam wadah tertutup. Selama minggu pertama fermentasi, tutup wadah harus dibuka sebentar setiap hari dengan tujuan .... <i>[MOTS - C3]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 36<br>Kelompok praktik IPA kelas IX membuat tapai singkong. Setelah singkong dikukus hingga matang, dalam keadaan masih panas singkong langsung ditaburi ragi tapai secara berlebihan, lalu ditutup rapat menggunakan wadah plastik yang kurang bersih. Setelah disimpan selama 3 hari, tapai singkong yang dihasilkan terasa sangat asam, berair, dan tidak manis.</th></tr></table>', 'none', '', '["Memasukkan cahaya matahari langsung agar cairan berubah warna menjadi hijau", "Melepaskan gas hasil fermentasi agar tekanan di dalam wadah tidak menyebabkan wadah meledak", "Menambahkan garam dapur secara bertahap setiap pagi", "Mengaduk cairan menggunakan sendok logam agar bakteri cepat mati"]'::jsonb, '[]'::jsonb, 'Melepaskan gas hasil fermentasi agar tekanan di dalam wadah tidak menyebabkan wadah meledak', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_36', 'PG', 'IPA SMP 9', 'Berdasarkan tahapan kerja kelompok tersebut, analisis penyebab utama tapai singkong menjadi terlalu asam dan tidak manis adalah .... <i>[HOTS - C4]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 37<br>Murid melakukan percobaan pengaruh suhu inkubasi selama 8 jam terhadap kualitas yoghurt menggunakan jenis starter dan volume susu yang sama. Berikut data hasil pengamatannya:<br>• Perlakuan A (Suhu 15 °C): pH akhir 6,2 | Tekstur: Masih cair seperti susu segar | Aroma: Segar khas susu.<br>• Perlakuan B (Suhu 42 °C): pH akhir 4,5 | Tekstur: Kental lembut homogen | Aroma: Asam segar khas yoghurt.<br>• Perlakuan C (Suhu 65 °C): pH akhir 6,4 | Tekstur: Cair sedikit pecah | Aroma: Susu masak.</th></tr></table>', 'none', '', '["Ragi yang ditaburkan saat singkong masih panas mematikan khamir (<i>Saccharomyces</i>) penghasil alkohol dan rasa manis, sehingga bakteri kontaminan penghasil asam mendominasi", "Singkong yang dikukus terlalu matang kehilangan seluruh kandungan karbohidrat (amilum)", "Wadah plastik tertutup rapat menghambat masuknya oksigen yang dibutuhkan jamur untuk membuat gula", "Waktu fermentasi 3 hari terlalu singkat sehingga amilum belum sempat dipecah sama sekali"]'::jsonb, '[]'::jsonb, 'Ragi yang ditaburkan saat singkong masih panas mematikan khamir (<i>Saccharomyces</i>) penghasil alkohol dan rasa manis, sehingga bakteri kontaminan penghasil asam mendominasi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_37', 'ESAI', 'IPA SMP 9', 'Berdasarkan data eksperimen tersebut, evaluasi ilmiah manakah yang paling tepat? (Pilih 2 jawaban benar) <i>[HOTS - C5 (</i><i>Pilihan</i><i> Ganda </i><i>Kompleks</i><i> — </i><i>Pilih</i><i> DUA </i><i>jawaban</i><i> yang </i><i>benar</i><i>)]</i><br>[  ] A. Suhu 42 °C merupakan suhu optimal bagi aktivitas metabolisme bakteri starter yoghurt dalam mengubah laktosa menjadi asam laktat.<br>[  ] B. Pada suhu 15 °C, bakteri yoghurt mengalami denaturasi enzim sehingga mati total.<br>[  ] C. Pada suhu 65 °C, bakteri asam laktat tidak aktif/mati akibat suhu terlalu tinggi sehingga tidak terjadi penurunan pH yang signifikan.<br>[  ] D. Semakin tinggi suhu inkubasi, semakin cepat proses pengasaman susu berlangsung tanpa batas maksimal.<br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 38<br>Di sekitar lingkungan sekolah terdapat industri rumah tangga tahu yang menghasilkan limbah cair (whey tahu) dalam jumlah banyak dan sering dibuang ke selokan sehingga menimbulkan bau tidak sedap. Selain itu, pedagang pasar tradisional membuang puluhan liter air kelapa tua setiap hari.</th></tr></table>', 'none', '', '[]'::jsonb, '[]'::jsonb, 'A dan C', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_38', 'PG', 'IPA SMP 9', 'Jika murid ingin mengolah limbah air kelapa tua tersebut menjadi produk bioteknologi konvensional bernilai gizi dan ekonomi sekaligus mengurangi pencemaran lingkungan, langkah analisis bahan dan mikroorganisme yang paling tepat adalah .... <i>[HOTS - C4]</i><br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Stimulus untuk Soal Nomor 39<br>Pengrajin tempe tradisional umumnya membungkus kedelai beragi menggunakan daun pisang, sedangkan pengrajin skala modern banyak menggunakan kantong plastik yang diberi lubang-lubang kecil menggunakan lidi/jarum. Keduanya bertujuan menjaga sirkulasi udara dan kelembapan selama pertumbuhan miselium Rhizopus sp.</th></tr></table>', 'none', '', '["Menyaring air kelapa tua, mendidihkannya dengan penambahan gula dan sumber nitrogen (ZA pangan/ekstrak kecambah), mengatur pH asam, lalu menginokulasi <i>Acetobacter </i><i>xylinum</i> untuk menghasilkan nata de coco", "Mencampur air kelapa tua dengan ragi tempe (<i>Rhizopus oryzae</i>) di tempat terbuka selama 24 jam untuk menghasilkan kecap manis", "Menambahkan ragi roti pada air kelapa tua tanpa pemanasan untuk menghasilkan keju keras", "Memfermentasi air kelapa tua menggunakan <i>Lactobacillus bulgaricus</i> hingga membentuk gumpalan tempe"]'::jsonb, '[]'::jsonb, 'Menyaring air kelapa tua, mendidihkannya dengan penambahan gula dan sumber nitrogen (ZA pangan/ekstrak kecambah), mengatur pH asam, lalu menginokulasi <i>Acetobacter </i><i>xylinum</i> untuk menghasilkan nata de coco', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_39', 'ESAI', 'IPA SMP 9', 'Evaluasilah perbandingan kedua teknik pengemasan tempe tersebut dari aspek biologis dan lingkungan! (Pilih 2 jawaban benar) <i>[HOTS - C5 (</i><i>Pilihan</i><i> Ganda </i><i>Kompleks</i><i> — </i><i>Pilih</i><i> DUA </i><i>jawaban</i><i> yang </i><i>benar</i><i>)]</i><br>[  ] A. Lubang-lubang kecil pada plastik maupun celah lipatan daun pisang mutlak diperlukan untuk menyuplai oksigen bagi respirasi aerob jamur <i>Rhizopus sp.</i><br>[  ] B. Kemasan plastik jauh lebih ramah lingkungan dibandingkan daun pisang karena dapat terurai oleh jamur tempe dalam waktu 2 hari.<br>[  ] C. Pembungkus daun pisang mampu menyerap kelebihan uap air hasil respirasi jamur sehingga mengurangi risiko pertumbuhan bakteri pembusuk akibat embun berlebih.<br>[  ] D. Jika plastik tidak diberi lubang sama sekali, jamur tempe akan tumbuh jauh lebih cepat karena kondisi anaerob total.', 'none', '', '[]'::jsonb, '[]'::jsonb, 'A dan C', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_09_40', 'ESAI', 'IPA SMP 9', 'Pilihlah SATU bahan pangan lokal yang mudah ditemukan di lingkungan sekitarmu (misalnya: singkong, ketan hitam, susu sapi segar, atau air kelapa). Rancanglah sebuah proyek pembuatan produk bioteknologi konvensional sederhana yang meliputi: (a) Nama produk dan mikroorganisme yang digunakan, (b) Urutan langkah kerja kritis beserta alasan ilmiahnya (minimal 4 tahap), dan (c) Satu variabel kontrol yang harus dijaga agar produk tidak gagal! <i>[HOTS - C6]</i><br><b>BAGIAN 3: KUNCI JAWABAN, PEMBAHASAN DETAIL &amp; RUBRIK PENILAIAN</b><br><b>Panduan Umum </b><b>Penskoran</b><b> (Total Skor </b><b>Maksimal</b><b> = 100):</b><br>• Pilihan Ganda Biasa (PG — 31 soal): Jawaban benar = skor 2; Jawaban salah/kosong = skor 0. (Subtotal = 62 poin)<br>• Pilihan Ganda Kompleks (PGK — 6 soal: No. 10, 12, 23, 25, 37, 39): Memilih 2 jawaban benar tepat = skor 3; Memilih 1 jawaban benar tanpa salah = skor 1,5; Ada pilihan salah = skor 0. (Subtotal = 18 poin)<br>• Uraian HOTS (3 soal: No. 13, 26, 40): Skor maksimal per soal = 6,67 (atau gunakan bobot: No. 13 = 7 poin, No. 26 = 7 poin, No. 40 = 6 poin -&gt; Subtotal = 20 poin).<br>• Nilai Akhir = (Total Skor Perolehan / 100) × 100.', 'none', '', '[]'::jsonb, '[]'::jsonb, 'Uraian (Rubrik)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_09_01', 'PG', 'Informatika SMP 9', 'Jaringan komputer adalah ....', 'none', '', '["Kumpulan komputer yang digunakan untuk bermain game", "Kumpulan perangkat yang saling terhubung untuk berbagi informasi dan sumber daya", "Perangkat untuk mencetak dokumen", "Program untuk mengolah angka"]'::jsonb, '[]'::jsonb, 'Kumpulan perangkat yang saling terhubung untuk berbagi informasi dan sumber daya', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_09_02', 'PG', 'Informatika SMP 9', 'Berpikir komputasional merupakan cara menyelesaikan masalah dengan ....', 'none', '', '["Mengandalkan keberuntungan", "Berpikir logis dan sistematis", "Menghafalkan semua jawaban", "Menggunakan komputer setiap saat"]'::jsonb, '[]'::jsonb, 'Berpikir logis dan sistematis', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_09_03', 'PG', 'Informatika SMP 9', 'Memecah masalah besar menjadi beberapa bagian kecil disebut ....', 'none', '', '["Abstraksi", "Algoritma", "Dekomposisi", "Simulasi"]'::jsonb, '[]'::jsonb, 'Dekomposisi', 10, 'Sesuai kunci jawaban.'),
